# options: take adjacent squares in coarse lattice and output uniform corner if equal else tile bg 7;
# maybe include all colors including 0; previous exact encoding attempts rejected. Generate shape variants and list colors.
for start_r in [0,1]:
 for end_trim in [0,1]:
  q=M[start_r:len(M)-end_trim if end_trim else len(M)]
  for start_c in [0,1]:
   for endc in [0,1]:
    qq=[row[start_c:len(row)-endc if endc else len(row)] for row in q]
