for top in (0,1):
 for bottom in (0,1):
  for left in (0,1):
   for right in (0,1):
    rows=M[top:len(M)-bottom if bottom else len(M)]
    q=[row[left:len(row)-right if right else len(row)] for row in rows]
    out=[[q[r][c] if q[r][c]!=0 and q[r][c]==q[r][c+1]==q[r+1][c]==q[r+1][c+1] else 7 for c in range(len(q[0])-1)] for r in range(len(q)-1)]
    print((top,bottom,left,right),len(out),len(out[0]),out)
